def peekn(seq, n):
    """Retrieve the first n elements of a sequence and the remaining sequence.

    Returns a tuple of (first_n_elements, remaining_sequence)
    The remaining sequence includes the elements retrieved.
    """
    iterator = iter(seq)
    first_n = tuple(itertools.islice(iterator, n))
    if len(first_n) < n:
        raise StopIteration
    return first_n, itertools.chain(first_n, iterator)


